SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_ckd_stage_hosp(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) NOT NULL,
  date_com varchar(14) NOT NULL,
  b_year varchar(4) NOT NULL,
	stage1 int(9) DEFAULT 0,
	stage2 int(9) DEFAULT 0,
	stage3 int(9) DEFAULT 0,
	stage4 int(9) DEFAULT 0,
	stage5 int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_ckd_stage_hosp WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_ckd_stage_hosp
(
SELECT
	 @id,h.hoscode hospcode,concat(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) as areacode
   ,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
	,COUNT(DISTINCT if(egfr_r1 >=90  ,CONCAT(HOSPCODE,'-',pid),NULL)) s1
	,COUNT(DISTINCT if(egfr_r1 BETWEEN 60 AND 89.99  ,CONCAT(HOSPCODE,'-',pid),NULL)) s2
	,COUNT(DISTINCT if(egfr_r1 BETWEEN 30 AND 59.99  ,CONCAT(HOSPCODE,'-',pid),NULL)) s3
	,COUNT(DISTINCT if(egfr_r1 BETWEEN 15 AND 29.99  ,CONCAT(HOSPCODE,'-',pid),NULL)) s4
	,COUNT(DISTINCT if(egfr_r1 < 15  ,CONCAT(HOSPCODE,'-',pid),NULL)) s5
FROM
t_ckd_egfr g INNER JOIN chospital h ON g.HOSPCODE=h.hoscode
WHERE egfr_r1 >0
GROUP BY g.hospcode
);
